  "/api/orgs": {
    "post": {
      "tags": [
        "Organizations"
      ],
      "summary": "Create organization",
      "description": "Creates a new organization and makes the current user an owner",
      "operationId": "createOrganization",
      "security": [
        {
          "cookieAuth": []
        }
      ],
      "requestBody": {
        "required": true,
        "content": {
          "application/json": {
            "schema": {
              "type": "object",
              "required": [
                "name",
                "slug"
              ],
              "properties": {
                "name": {
                  "type": "string",
                  "description": "Organization name",
                  "example": "Acme Inc."
                },
                "slug": {
                  "type": "string",
                  "description": "URL-friendly unique identifier",
                  "pattern": "^[a-z0-9-]+$",
                  "example": "acme-inc"
                },
                "logo": {
                  "type": "string",
                  "format": "uri",
                  "description": "Organization logo URL",
                  "nullable": true
                }
              }
            }
          }
        }
      },
      "responses": {
        "201": {
          "description": "Organization created successfully",
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "success": {
                    "type": "boolean",
                    "example": true
                  },
                  "data": {
                    "$ref": "#/components/schemas/Organization"
                  }
                }
              }
            }
          }
        },
        "400": {
          "description": "Validation error",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/Error"
              }
            }
          }
        },
        "401": {
          "description": "Unauthorized",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/Error"
              }
            }
          }
        },
        "409": {
          "description": "Organization slug already exists",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/Error"
              }
            }
          }
        },
        "501": {
          "description": "Not implemented",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/Error"
              }
            }
          }
        }
      }
    }
  },
