  "/api/support/conversations/{id}/messages": {
    "get": {
      "tags": [
        "Support"
      ],
      "summary": "Get a conversation's message thread",
      "description": "Returns the most recent window of messages in ascending (oldest-first) order, ready to render as a chat thread. `hasMore: true` means older history exists above the returned window - this endpoint always anchors to the newest messages, never to an arbitrary page. All kinds (`incoming`, `outgoing`, `note`, `activity`) are included, private notes too, since this is the agent-facing thread pane. Outgoing messages carry delivery detail for the retry UI: `deliveryError` (short sanitized text or null), `senderBlocked` (true when the failure is `SENDER_DOMAIN_NOT_AUTHORIZED`: the message was never submitted to the provider) and `retryable` (true only for a failed reply that has an email outbox entry; CSAT survey deliveries are never retryable).\n",
      "operationId": "listSupportConversationMessages",
      "parameters": [
        {
          "in": "path",
          "name": "id",
          "required": true,
          "schema": {
            "type": "string"
          }
        },
        {
          "in": "query",
          "name": "limit",
          "schema": {
            "type": "integer",
            "minimum": 1,
            "maximum": 500,
            "default": 200
          }
        }
      ],
      "responses": {
        "200": {
          "description": "Message thread",
          "oldest first": null
        },
        "403": {
          "description": "Not a member of this inbox or a project admin"
        },
        "404": {
          "description": "Conversation not found"
        }
      }
    },
    "post": {
      "tags": [
        "Support"
      ],
      "summary": "Write an agent reply or an internal note to a conversation",
      "description": "Only `outgoing` (customer-visible reply) and `note` (internal-only) kinds may be created here - `incoming` is written by the mail pipeline and `activity` by the system, never by an agent directly. `isPrivate` is derived from `kind` server-side and is never taken from the request body, since a private note rendered as a public reply is the worst failure mode in a support tool. An `outgoing` message atomically claims an unassigned conversation for the replying agent, writes the matching activity, and enqueues the durable outbox delivery in the same transaction; a `note` never claims or dispatches mail.\n",
      "operationId": "createSupportConversationMessage",
      "parameters": [
        {
          "in": "path",
          "name": "id",
          "required": true,
          "schema": {
            "type": "string"
          }
        }
      ],
      "responses": {
        "200": {
          "description": "Message created"
        },
        "400": {
          "description": "Validation failed"
        },
        "403": {
          "description": "Not a member of this inbox or a project admin"
        },
        "404": {
          "description": "Conversation not found"
        },
        "409": {
          "description": "The inbox has no sending address, the contact has no email address, or (project sender policy) the inbox's From address is on a domain the project has not verified (SENDER_NOT_VERIFIED)"
        }
      }
    }
  },
  "/api/support/conversations/{id}/messages/{messageId}/retry": {
    "post": {
      "tags": [
        "Support"
      ],
      "summary": "Retry a failed outgoing reply",
      "description": "Only a message whose `deliveryStatus` is `failed` can be retried - an agent-initiated retry is a deliberate decision to try again from scratch (`resetOutboundDeliveryForRetry`), not one more of the outbox worker's own automatic attempts. Triggers a worker pass immediately rather than waiting for the next unrelated reply to piggyback on. The sender is checked first: when the From stored on the delivery is still not authorized for the project, the retry is refused with 409 `SENDER_NOT_VERIFIED` and nothing is reset. Deliveries that are not replies (`kind: csat` surveys) have no retry; the thread API marks them `retryable: false` and this endpoint answers 404. `previousSubmissionAttempted` is false when the previous failure was the sender block (`SENDER_DOMAIN_NOT_AUTHORIZED`): nothing was ever submitted to the provider, so there is no duplicate risk.\n",
      "operationId": "retrySupportConversationMessage",
      "parameters": [
        {
          "in": "path",
          "name": "id",
          "required": true,
          "schema": {
            "type": "string"
          }
        },
        {
          "in": "path",
          "name": "messageId",
          "required": true,
          "schema": {
            "type": "string"
          }
        }
      ],
      "responses": {
        "200": {
          "description": "Retry queued"
        },
        "403": {
          "description": "Not a member of this inbox or a project admin"
        },
        "404": {
          "description": "Conversation",
          "message": null,
          "or its outbox row not found": null
        },
        "409": {
          "description": "The message is not in a failed delivery state, or its sender is still not verified (SENDER_NOT_VERIFIED)"
        }
      }
    }
  },
